package tr.gov.kocaeli.sehir.audit.application;
import com.fasterxml.jackson.databind.ObjectMapper;import org.slf4j.MDC;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import tr.gov.kocaeli.sehir.common.security.CurrentUserService;import java.util.UUID;
@Service public class AuditService{private final JdbcTemplate jdbc;private final CurrentUserService current;private final ObjectMapper mapper;public AuditService(JdbcTemplate jdbc,CurrentUserService current,ObjectMapper mapper){this.jdbc=jdbc;this.current=current;this.mapper=mapper;}public void record(String action,String type,UUID id,Object before,Object after){try{jdbc.update("insert into audit_log(actor_id,action,entity_type,entity_id,before_value,after_value,trace_id) values(?,?,?,?,?::jsonb,?::jsonb,?)",current.require().id(),action,type,id,before==null?null:mapper.writeValueAsString(before),after==null?null:mapper.writeValueAsString(after),MDC.get("traceId"));}catch(Exception e){throw new IllegalStateException("Audit kaydı yazılamadı",e);}}}
